html:
{%- set ctx = dgi_report_context(doc) -%}
{%- set d = ctx.data -%}
{%- macro m(v) -%}{{ frappe.utils.fmt_money(v or 0, currency="CDF") }}{%- endmacro -%}
{%- macro q(v) -%}{{ ("%.3f"|format(v or 0)).rstrip("0").rstrip(".") }}{%- endmacro -%}
<div class="rf">
<style>
  .rf{font-family:Arial,Helvetica,sans-serif;font-size:10.5px;color:#1b1b1b;}
  .rf table{border-collapse:collapse;width:100%;}
  .rf h2{font-size:17px;margin:0 0 6px 0;color:#12355b;text-align:center;letter-spacing:.3px;}
  .rf h4{font-size:11.5px;margin:10px 0 4px 0;color:#12355b;border-bottom:1px solid #12355b;padding-bottom:2px;}
  .rf .head td{padding:1px 4px;}
  .rf .head td.k{color:#555;width:30%;text-align:right;padding-right:10px;}
  .rf .g th{background:#12355b;color:#fff;font-size:9.5px;padding:3px;border:1px solid #12355b;text-align:right;}
  .rf .g td{border:1px solid #d5dbe3;padding:2px 4px;text-align:right;font-size:9.5px;}
  .rf .g .l{text-align:left;} .rf .g .c{text-align:center;}
  .rf .g tr.tot td{font-weight:bold;background:#eef2f7;}
  .rf .g tr.typ td{border-top:1.5px solid #12355b;}
  .rf .muted{color:#888;}
  .rf .foot{margin-top:8px;font-size:7.5px;color:#888;text-align:center;}
</style>

<h2>{% if ctx.kind == "Z" %}RAPPORT Z N° {{ doc.sequence_no }}{% elif ctx.kind == "A" %}RAPPORT A N° {{ doc.sequence_no }}{% elif doc.report_type == "X périodique" %}RAPPORT X PÉRIODIQUE N° {{ doc.sequence_no }}{% else %}RAPPORT X QUOTIDIEN N° {{ doc.sequence_no }}{% endif %}</h2>
<table class="head">
  <tr><td class="k">Dénomination commerciale</td><td><b>{{ doc.company_name|e }}</b></td></tr>
  <tr><td class="k">NIF</td><td>{{ doc.nif|e }}</td></tr>
  <tr><td class="k">ISF</td><td>{{ doc.isf|e }}</td></tr>
  <tr><td class="k">Date et heure du rapport</td><td>{{ ctx.generated_on }}</td></tr>
  <tr><td class="k">Début de période</td><td>{{ ctx["from"] }}</td></tr>
  <tr><td class="k">Fin de période</td><td>{{ ctx.to }}</td></tr>
  <tr><td class="k">Généré par</td><td>{{ ctx.generated_by|e }} ({{ doc.generated_by|e }})</td></tr>
</table>

{% if ctx.kind != "A" %}
<h4>Section 1 : Totaux par type de facture (CDF)</h4>
<table class="g">
  <thead><tr><th class="l">Type</th><th>Nombre de factures</th><th>Factures incomplètes</th><th>Montant total</th><th>Montant HT</th><th>Montant de la TVA</th><th>Taxe spécifique</th></tr></thead>
  <tbody>
  {% for t in ctx.types %}{% set s = d.by_type[t] %}
    <tr><td class="l"><b>{{ t }}</b></td><td>{{ s.count }}</td><td>{{ s.incomplete }}</td><td>{{ m(s.total) }}</td><td>{{ m(s.ht) }}</td><td>{{ m(s.vat) }}</td><td>{{ m(s.ts) }}</td></tr>
  {% endfor %}
  </tbody>
</table>

<h4>Section 2 : Totaux par groupe de taxation par type de facture (CDF)</h4>
<table class="g">
  <thead><tr><th class="l">Type</th><th class="c">Groupe</th><th>Montant total</th><th>Montant HT</th><th>Montant de la TVA</th><th>Taxe spécifique</th></tr></thead>
  <tbody>
  {% for t in ctx.types %}
    {% if d.by_type[t].count %}
      {% for g, v in d.by_type_group[t].items() %}
        <tr class="{{ 'typ' if loop.first else '' }}"><td class="l">{% if loop.first %}<b>{{ t }}</b>{% endif %}</td><td class="c">{{ g }}</td><td>{{ m(v.total) }}</td><td>{{ m(v.ht) }}</td><td>{{ m(v.vat) }}</td><td>{{ m(v.ts) }}</td></tr>
      {% endfor %}
    {% else %}
      <tr class="typ"><td class="l"><b>{{ t }}</b></td><td class="c muted" colspan="5">aucune facture sur la période (tous groupes A à S : 0,00)</td></tr>
    {% endif %}
  {% endfor %}
  </tbody>
</table>

<h4>Section 3 : Totaux par type de paiement (CDF)</h4>
<table class="g">
  <thead><tr><th class="l">Type de paiement</th><th>Ventes</th><th>Avoirs (remboursements)</th><th>Net</th></tr></thead>
  <tbody>
  {% for p in d.payments %}<tr><td class="l">{{ p.label }}</td><td>{{ m(p.sales) }}</td><td>{{ m(p.credits) }}</td><td>{{ m(p.net) }}</td></tr>{% endfor %}
  </tbody>
</table>

<h4>Section 4 : Réductions commerciales (CDF)</h4>
<table class="g">
  <thead><tr><th class="l">Type de facture</th><th>Montant des réductions</th><th>Montant des réductions d'impôt</th></tr></thead>
  <tbody>
  {% for t in ctx.types %}<tr><td class="l">{{ t }}</td><td>{{ m(d.reductions[t].amount) }}</td><td>{{ m(d.reductions[t].tax) }}</td></tr>{% endfor %}
  </tbody>
</table>

<h4>Section 5 : Autres enregistrements ayant réduit les ventes (factures d'avoir, CDF)</h4>
<table class="g">
  <thead><tr><th class="l">Nature</th><th>Nombre</th><th>Montant total</th></tr></thead>
  <tbody>
  {% for n in d.natures %}<tr><td class="l">{{ n.code }} – {{ n.label }}</td><td>{{ n.count }}</td><td>{{ m(n.total) }}</td></tr>{% endfor %}
  </tbody>
</table>

<h4>Synthèse</h4>
<table class="g">
  <tbody>
    <tr><td class="l">Nombre total de factures</td><td>{{ d.summary.count }}</td></tr>
    <tr><td class="l">Nombre de ventes incomplètes</td><td>{{ d.incomplete_total }}</td></tr>
    <tr><td class="l">Total des ventes (FV, FT, EV, ET)</td><td>{{ m(d.summary.sales_total) }}</td></tr>
    <tr><td class="l">Total des avoirs (FA, EA)</td><td>{{ m(d.summary.credits_total) }}</td></tr>
    <tr class="tot"><td class="l">Total net TTC</td><td>{{ m(d.summary.net_total) }}</td></tr>
    <tr class="tot"><td class="l">TVA nette</td><td>{{ m(d.summary.net_vat) }}</td></tr>
  </tbody>
</table>
{% else %}
<h4>Détail par article (CDF)</h4>
<table class="g">
  <thead><tr><th class="c">#</th><th class="l">Code</th><th class="l">Désignation</th><th>Prix unitaire</th><th class="c">Groupe</th><th>Taux d'impôt</th><th>Qté vendue</th><th>Qté retournée</th><th>Montant</th><th>Qté en stock</th></tr></thead>
  <tbody>
  {% for a in d.articles %}
    <tr><td class="c">{{ loop.index }}</td><td class="l">{{ a.code|e }}</td><td class="l">{{ a.name|e }}</td><td>{{ m(a.price) }}</td><td class="c">{{ a.group }}</td><td>{{ "%g"|format(a.rate or 0) }} %</td><td>{{ q(a.qty_sold) }}</td><td>{{ q(a.qty_returned) }}</td><td>{{ m(a.amount) }}</td><td>{% if a.stock is not none %}{{ q(a.stock) }}{% else %}<span class="muted">n/a</span>{% endif %}</td></tr>
  {% else %}
    <tr><td colspan="10" class="c muted">Aucun article vendu sur la période</td></tr>
  {% endfor %}
    <tr class="tot"><td colspan="6" class="l">Total ({{ d.summary.count }} articles)</td><td>{{ q(d.summary.qty_sold) }}</td><td>{{ q(d.summary.qty_returned) }}</td><td>{{ m(d.summary.amount) }}</td><td></td></tr>
  </tbody>
</table>
{% endif %}

<div class="foot">{{ doc.company_name|e }} – NIF {{ doc.nif|e }} – ISF {{ doc.isf|e }} – {{ doc.name }} – ERPNext / DGI Compliance v5.0.0</div>
</div>
